def create_app(workflow: Workflow, ops: OpsReader, auth, session_key: str, static_dir: Path | None = None,
               exports=None) -> FastAPI:
    if not session_key:
        raise ValueError("a session key is required (ALLOCATION_SESSION_KEY)")
    app = FastAPI(title="MJH allocation pilot", docs_url="/api/docs", openapi_url="/api/openapi.json")
    signer = URLSafeTimedSerializer(session_key, salt="allocation-session")

    @app.middleware("http")
    async def correlation(request: Request, call_next):
        request.state.correlation_id = request.headers.get("X-Correlation-ID") or uuid.uuid4().hex
        response = await call_next(request)
        response.headers["X-Correlation-ID"] = request.state.correlation_id
        return response

    @app.exception_handler(Refused)
    async def refused(_, exc: Refused):
        return JSONResponse({"code": exc.code, "detail": str(exc)}, status_code=422)

